// Theme Management (Default: Crisp Light Theme)
function initTheme() {
  const savedTheme = localStorage.getItem('gp_seo_theme') || 'light';
  applyTheme(savedTheme);
}

function applyTheme(theme) {
  document.documentElement.setAttribute('data-theme', theme);
  document.body.setAttribute('data-theme', theme);
  localStorage.setItem('gp_seo_theme', theme);

  const themeIcon = document.getElementById('themeIcon');
  const themeText = document.getElementById('themeText');
  if (theme === 'dark') {
    if (themeIcon) themeIcon.innerText = '☀️';
    if (themeText) themeText.innerText = 'Light Mode';
  } else {
    if (themeIcon) themeIcon.innerText = '🌙';
    if (themeText) themeText.innerText = 'Dark Mode';
  }
}

function toggleTheme() {
  const current = document.documentElement.getAttribute('data-theme') || 'light';
  const next = current === 'dark' ? 'light' : 'dark';
  applyTheme(next);
}

// Navigation Handling
function initNavigation() {
  const navItems = document.querySelectorAll('.nav-item');
  const sections = document.querySelectorAll('.view-section');
  const pageTitle = document.getElementById('currentPageTitle');

  navItems.forEach(item => {
    item.addEventListener('click', () => {
      const target = item.dataset.target;
      navItems.forEach(n => n.classList.remove('active'));
      sections.forEach(s => s.classList.remove('active'));

      item.classList.add('active');
      const targetSection = document.getElementById(target);
      if (targetSection) targetSection.classList.add('active');

      if (pageTitle) {
        pageTitle.innerText = item.querySelector('span:not(.icon):not(.nav-badge)').innerText;
      }
    });
  });
}

// Load Crawl Data
async function loadAuditData() {
  if (window.AUDIT_RAW_DATA && window.AUDIT_RAW_DATA.pages) {
    auditData = window.AUDIT_RAW_DATA;
    processAndRenderData();
    return;
  }

  try {
    const res = await fetch(`${API_BASE}/api/data`);
    if (res.ok) {
      auditData = await res.json();
    } else {
      const fallback = await fetch('audit_raw_data.json');
      auditData = await fallback.json();
    }
  } catch (err) {
    try {
      const fallback = await fetch('audit_raw_data.json');
      auditData = await fallback.json();
    } catch (e2) {
      console.error('Failed to load audit data:', e2);
    }
  }

  processAndRenderData();
}

function processAndRenderData() {
  if (auditData && auditData.pages) {
    allPages = Object.entries(auditData.pages).map(([url, data]) => ({ url, ...data }));
    missingAltImages = auditData.images_summary?.sample_missing_alt || [];
    renderDashboardOverview();
    renderTechnicalSEO();
    renderOnPageSEO();
    renderMediaEngine();
  }
}

