function suggestAlt(src) {
  const filename = src.split('/').pop().replace(/\.[^/.]+$/, "").replace(/[-_]/g, " ");
  const suggested = `Guru Punvaanii Real Estate - ${filename.charAt(0).toUpperCase() + filename.slice(1)}`;
  navigator.clipboard.writeText(suggested);
  alert(`Copied Suggested Alt Text:\n"${suggested}"`);
}

// Schema Generator Studio
function initSchemaGenerator() {
  const typeSelect = document.getElementById('schemaTypeSelect');
  const projNameInput = document.getElementById('schemaProjectName');
  const projLocationInput = document.getElementById('schemaProjectLocation');
  const projPriceInput = document.getElementById('schemaProjectPrice');
  const reraInput = document.getElementById('schemaReraNo');
  const codeOutput = document.getElementById('schemaJsonOutput');
  const copyBtn = document.getElementById('copySchemaBtn');

  const updateSchema = () => {
    const type = typeSelect ? typeSelect.value : 'RealEstateAgent';
    const name = (projNameInput && projNameInput.value) || 'Guru Punvaanii Properties';
    const loc = (projLocationInput && projLocationInput.value) || 'Anekal, Bangalore, Karnataka';
    const price = (projPriceInput && projPriceInput.value) || 'INR 35,00,000 Onwards';
    const rera = (reraInput && reraInput.value) || 'PRM/KA/RERA/1251/308/PR/200924/007089';

    let schemaObj = {};

    if (type === 'RealEstateAgent') {
      schemaObj = {
        "@context": "https://schema.org",
        "@type": "RealEstateAgent",
        "@id": "https://gurupunvaanii.com/#organization",
        "name": name,
        "url": "https://gurupunvaanii.com/",
        "logo": "https://gurupunvaanii.com/wp-content/uploads/2026/03/guru-punvaanii-logo.png",
        "description": "Premium BMRDA, BDA, and RERA-approved plotted developments and luxury villas in Karnataka.",
        "telephone": "+91-80-XXXXXXXX",
        "priceRange": price,
        "address": {
          "@type": "PostalAddress",
          "streetAddress": "Bangalore Corporate Office",
          "addressLocality": "Bengaluru",
          "addressRegion": "Karnataka",
          "addressCountry": "IN"
        },
        "geo": {
          "@type": "GeoCoordinates",
          "latitude": "12.989404",
          "longitude": "77.576850"
        }
      };
    } else if (type === 'SingleFamilyResidence') {
      schemaObj = {
        "@context": "https://schema.org",
        "@type": "SingleFamilyResidence",
        "name": name,
        "description": `Luxury climate-controlled residential villa project situated in ${loc}.`,
        "address": {
          "@type": "PostalAddress",
          "addressLocality": loc,
          "addressRegion": "Karnataka",
          "addressCountry": "IN"
        },
        "offers": {
          "@type": "Offer",
          "price": price,
          "priceCurrency": "INR",
          "availability": "https://schema.org/InStock"
        },
        "identifier": rera
      };
    } else {
      schemaObj = {
        "@context": "https://schema.org",
        "@type": "Product",
        "name": `${name} - Plotted Development`,
        "description": `BMRDA approved premium residential villa plots in ${loc}.`,
        "offers": {
          "@type": "Offer",
          "price": price,
          "priceCurrency": "INR",
          "availability": "https://schema.org/InStock"
        },
        "additionalProperty": [
          { "@type": "PropertyValue", "name": "RERA Registration", "value": rera },
          { "@type": "PropertyValue", "name": "Approval Authority", "value": "BMRDA / BDA Approved" }
        ]
      };
    }

    if (codeOutput) {
      codeOutput.innerText = JSON.stringify(schemaObj, null, 2);
    }
  };

  if (typeSelect) typeSelect.addEventListener('change', updateSchema);
  if (projNameInput) projNameInput.addEventListener('input', updateSchema);
  if (projLocationInput) projLocationInput.addEventListener('input', updateSchema);
  if (projPriceInput) projPriceInput.addEventListener('input', updateSchema);
  if (reraInput) reraInput.addEventListener('input', updateSchema);

  if (copyBtn) {
    copyBtn.addEventListener('click', () => {
      if (codeOutput) {
        navigator.clipboard.writeText(codeOutput.innerText);
        copyBtn.innerText = 'Copied!';
        setTimeout(() => copyBtn.innerText = 'Copy JSON-LD', 2000);
      }
    });
  }

  updateSchema();
}

